const inp = $input.first().json;
const body = inp.body || inp;
return [{
  json: {
    wpBaseUrl: $env.WP_BASE_URL || 'http://host.docker.internal:10020',
    wpAuth: 'Basic ' + Buffer.from(($env.WP_USERNAME || '') + ':' + ($env.WP_APP_PASSWORD || '')).toString('base64'),
    slackToken: $env.SLACK_BOT_TOKEN || '',
    slackChannel: (typeof body.channel_id === 'string' && body.channel_id) ? body.channel_id : ($env.SLACK_DEFAULT_CHANNEL || ''),
    cpts: ['blog', 'press-release', 'case-study', 'whitepaper'],
  }
}];

const config = $('Load Config').first().json;
const cpts = config.cpts;
const wpBase = config.wpBaseUrl;
const wpAuth = config.wpAuth;

const allDrafts = [];

for (const cpt of cpts) {
  let url = wpBase + '/wp-json/wp/v2/' + cpt + '?status=draft&per_page=10&orderby=modified&order=desc&_fields=id,title,slug,status,modified,author';
  // Swap spaces for %20 just in case
  url = url.replace(/ /g, '%20');

  let response;
  try {
    response = await $helpers.httpRequest({
      method: 'GET',
      url,
      headers: { Authorization: wpAuth },
    });
  } catch (e) {
    // Skip CPTs that error (e.g. not found)
    continue;
  }

  const posts = Array.isArray(response) ? response : [];
  for (const post of posts) {
    allDrafts.push({
      id: post.id,
      cpt,
      title: (post.title?.rendered || post.title || 'Untitled').trim(),
      slug: post.slug,
      modified: post.modified ? new Date(post.modified).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : '',
      editLink: wpBase + '/wp-admin/post.php?post=' + post.id + '&action=edit',
    });
  }
}

// Sort by modified date descending (already sorted per CPT, just interleave)
return [{ json: { drafts: allDrafts, count: allDrafts.length } }];

const { drafts, count } = $input.first().json;
const config = $('Load Config').first().json;

const cptLabels = {
  blog: 'Blog',
  'press-release': 'Press Release',
  'case-study': 'Case Study',
  whitepaper: 'Whitepaper',
};

let text;
if (count === 0) {
  text = 'No drafts found.';
} else {
  text = drafts.map(d => {
    const label = cptLabels[d.cpt] || d.cpt;
    return '\u2022 *' + d.title + '* [' + label + '] \u2014 modified ' + d.modified + ' \u2014 <' + d.editLink + '|Edit>';
  }).join('\n');
}

const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: 'Drafts: ' + count + ' pending', emoji: true }
  },
  {
    type: 'section',
    text: { type: 'mrkdwn', text: count > 0 ? text : '_No drafts found across Blog, Press Release, Case Study, and Whitepaper._' }
  }
];

return [{
  json: {
    channel: config.slackChannel,
    slackToken: config.slackToken,
    text: count + ' draft' + (count !== 1 ? 's' : '') + ' pending review',
    blocks,
  }
}];
